usability_ui <- function(id) { ns<-NS(id); lab_section(c("Inspect an interface against a heuristic.","Describe an observable issue rather than a preference.","Suggest a change and explain its effect."),tagList(p("Scenario · A booking form shows no confirmation after submission."), selectInput(ns("heuristic"),"Choose a review lens",c("Visibility of system status","Match with the real world","User control and freedom","Consistency and standards","Error prevention")), textAreaInput(ns("note"),"What could confuse someone?",rows=3,placeholder="Describe the moment, impact, and a possible improvement."), actionButton(ns("review"),"Review my note",class="btn-primary"), uiOutput(ns("feedback"))),"Which part of your note is evidence from the scenario, and which part is your interpretation?") }
usability_server <- function(id) { moduleServer(id,function(input,output,session){ reviewed<-reactiveVal(FALSE); observeEvent(input$review,reviewed(TRUE)); output$feedback<-renderUI({if(!reviewed()) return(NULL); if(nchar(trimws(input$note))<20) return(div(class="alert alert-warning mt-3","Add a little more detail: name the issue and its possible effect.")); div(class="alert alert-success mt-3",tags$strong("Formative prompt · "),paste("Connect your observation to",tolower(input$heuristic),"and propose one testable change."))}) }) }
